static void app_icon_click_cb(lv_event_t *e)
{
    lv_obj_t *btn = lv_event_get_target(e);
    const char *name = (const char *)lv_obj_get_user_data(btn);
    LV_LOG_USER("Launch app: %s", name ? name : "unknown");
    reset_idle_timer();

    /* Press-in bounce: 1.0→0.85→1.0 with ease-out bounce for a lively
     * rebound. SHRINK-ONLY so nothing ever clips the dock container. */
    lv_anim_t a;
    lv_anim_init(&a);
    lv_anim_set_var(&a, btn);
    lv_anim_set_exec_cb(&a, scale_bounce_cb);
    lv_anim_set_values(&a, 256, 218);   /* 1.0x → 0.85x */
    lv_anim_set_time(&a, 90);
    lv_anim_set_playback_time(&a, 220);
    lv_anim_set_path_cb(&a, lv_anim_path_bounce);
    lv_anim_set_repeat_count(&a, 1);
    lv_anim_set_ready_cb(&a, launch_app_after_bounce);
    lv_anim_set_user_data(&a, (void *)name);
    lv_anim_start(&a);

    /* Shadow pulse on the button itself for tactile feedback */
    lv_anim_t s;
    lv_anim_init(&s);
    lv_anim_set_var(&s, btn);
    lv_anim_set_exec_cb(&s, shadow_pulse_cb);
    lv_anim_set_values(&s, 0, 28);
    lv_anim_set_time(&s, 90);
    lv_anim_set_playback_time(&s, 150);
    lv_anim_set_repeat_count(&s, 1);
    lv_anim_start(&s);
}

static void scale_bounce_cb(void *obj, int32_t v)
{
    lv_obj_set_style_transform_scale((lv_obj_t *)obj, v, 0);
}

static void shadow_pulse_cb(void *obj, int32_t v)
{
    lv_obj_set_style_shadow_width((lv_obj_t *)obj, v, 0);
}

static void launch_app_after_bounce(lv_anim_t *a)
{
    const char *name = (const char *)lv_anim_get_user_data(a);
    if      (strcmp(name, "music") == 0)    show_subpage("Music");
    else if (strcmp(name, "games") == 0)    show_subpage("Games");
    else if (strcmp(name, "books") == 0)    show_subpage("Books");
    else if (strcmp(name, "files") == 0)    show_subpage("Files");
    else if (strcmp(name, "ai") == 0)       show_subpage("AI");
    else if (strcmp(name, "settings") == 0) show_subpage("Settings");
}

