static void focus_cb(lv_group_t *group)
{
    lv_obj_t *focused = lv_group_get_focused(group);
    if (!focused) return;

    if (g_focused_btn && g_focused_btn != focused)
        lv_anim_delete(g_focused_btn, NULL);

    g_focused_btn = focused;

